from collections import Counter
def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg]
    bycol={}
    for r,c,col in cells: bycol.setdefault(col,[]).append((r,c))
    bcol=max(bycol, key=lambda c:len(bycol[c]))
    singles={c for c,v in bycol.items() if len(v)==1}
    assert len(singles)==1,(singles,bcol,bycol)
    (sr,sc,sy)=next(iter(bycol[singles.pop()])); 
    brs=[r for r,c in bycol[bcol]]; bcs=[c for r,c in bycol[bcol]]
    bh=max(brs)-min(brs)+1; bw=max(bcs)-min(bcs)+1
    drow = 1 if sr>max(brs) else (-1 if sr<min(brs) else 0)
    dcol = -1 if sc<min(bcs) else (1 if sc>max(bcs) else 0)
    dy,dz=drow*bh,dcol*bw
    o=[row[:] for row in g]
    rr,cc=min(brs)+dy,min(bcs)+dz
    while 0<=rr and rr+bh<=h and 0<=cc and cc+bw<=w:
        for dr in range(bh):
            for dc in range(bw):
                o[rr+dr][cc+dc]=sy
        rr+=dy; cc+=dz
    return o
